const campus=[{"id": "main", "name": "본관", "category": "학원 중추", "x": 535, "y": 320, "desc": "첨탑에는 교장실과 학생회실, 로비에는 파견 임무 게시판과 상점이 있다. 지하 훈련장은 인공조명으로 운영한다."}, {"id": "dorm", "name": "기숙사", "category": "학생 생활", "x": 680, "y": 460, "desc": "약 800명의 학생이 생활한다. 학부 구분 없이 상·하급생으로 나뉘며, 주말에는 외출과 휴식을 권장한다."}, {"id": "town", "name": "페리 타운", "category": "상업 · 숙박", "x": 350, "y": 490, "desc": "대장간·음식점·여관이 모인 마을. 차원문과 선박으로 온 관광객들이 머문다. 나스카의 개인 대장간도 이곳에 있다."}, {"id": "tower", "name": "소마탑", "category": "차원문 · 연구", "x": 213, "y": 390, "desc": "2층의 차원문은 각국 수도와 연결되며 소규모 물류 허브를 겸한다. 동방연합의 연결 지점은 대마탑 1층이다. 3~9층은 도서관·강의실·연구실이다.\n개인 왕복: 공용폐 20만 또는 왕복 코인 1개. 귀환할 때는 마도단말로 연락한다."}, {"id": "coral", "name": "산호 군락", "category": "탐사 · 위험 구역", "x": 864, "y": 505, "desc": "크고 작은 동굴에 해양 마수의 둥지가 많다. 학교에서 도보로 접근할 수 있다."}, {"id": "training", "name": "야외 훈련장", "category": "실전 훈련", "x": 645, "y": 685, "desc": "얕은 바다를 활용하는 야외 훈련 구역. 본관 지하의 실내 훈련장과 함께 사용한다."}, {"id": "gate", "name": "성문", "category": "출입 · 연결", "x": 468, "y": 614, "desc": "교내 생활 구역과 소마탑·산호 군락을 잇는 출입부."}];
const world=[{"id": "kreuz", "name": "크로이츠 공화국", "category": "철혈계 · 군사와 마공학", "desc": "수도 크루시온의 중앙 사령부와 군항 델프리슈타인을 중심으로 군사력을 운용한다. 부유석 공중전함·전차·무기 산업이 발달했다.\n튜로 황무지에는 자원이 풍부하며, 심부 촌락에는 언데드 습격이 잦다."}, {"id": "opera", "name": "오페라 시국", "category": "철혈계 · 광물과 생명공학", "desc": "루비화산의 광물과 괴수 부위 이식 기술로 발전한 도시국가. 시민의 빈부·계급 격차가 크며, 실종자들이 비밀 실험의 재료로 쓰인다.\n비공식 범죄조직 카나리아 클럽이 암약한다."}, {"id": "zerge", "name": "제르게시아 왕국", "category": "환상계 · 기사와 번영", "desc": "수도 디어 마리앙느와 농업도시 가우초를 둔 인구 최다의 강국. 강력한 기사단과 높은 치안으로 번영하며 농산물·세공품을 수출한다. 리체인 교국과 동맹 관계다.\n영내에서 카나리아 클럽의 활동이 관측된다."}, {"id": "eastern", "name": "동방연합", "category": "환상계 · 마법과 교역", "desc": "수도 해천의 99층 대마탑은 마법과 교역의 중심이다. 1층은 마법 백화점, 지하는 청반병 환자 격리실로 쓰인다. 거대어 부산물이 주수출품이며 크로이츠와 교류한다."}, {"id": "betia", "name": "베티아 왕국", "category": "신앙계 · 반역왕의 통치", "desc": "약 150년 전 신앙 모방죄로 파문당한 초대 반역왕이 건국했다. 왕도 루미나리에트와 크레스티아 협곡을 두고 베티아 근위대를 운용한다."}, {"id": "richein", "name": "리체인 교국", "category": "신앙계 · 모신교의 본산", "desc": "수도 스카이아의 대성당을 중심으로 모신 트레사를 섬긴다. 신성력은 트레사의 마력에서 비롯된다. 모신의 취향을 반영한 간식 상점과 숲속 마을 기아나가 있다."}, {"id": "lake", "name": "운석호", "category": "동방연합 · 별도 탐사 지역", "desc": "폭 약 50km, 깊이 약 8km. 거대어 사냥과 부산물 수출의 터전이다. 3년 전부터 나타난 청와와 청반병의 위험이 존재한다."}, {"id": "floren", "name": "플로렌 옛터", "category": "크로이츠 · 별도 탐사 지역", "desc": "튜로 황무지 심부에 남은 옛 도시. 주변 촌락은 잦은 언데드 습격에 시달린다."}];
function el(tag,attrs={},parent){const n=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);if(parent)parent.append(n);return n;}
const pts=p=>p.map(v=>v.join(',')).join(' ');
function poly(g,p,cls){return el('polygon',{points:pts(p),class:cls},g);}
function path(g,d,cls,extra={}){return el('path',{d,class:cls,...extra},g);}
function label(g,x,y,t,cls='atlas-caption'){
 const boxed=cls==='atlas-country-name'||cls==='atlas-zone-name';
 const parent=boxed?el('g',{class:'atlas-nameplate','pointer-events':'none'},g):g;
 const node=el('text',{x,y,class:cls,'text-anchor':'middle','pointer-events':'none'},parent);node.textContent=t;
 if(boxed){const b=node.getBBox(),world=g.ownerSVGElement?.getAttribute('data-atlas-mode')==='world';const pad=world?15:10;const rect=el('rect',{x:b.x-pad,y:b.y-pad*.65,width:b.width+pad*2,height:b.height+pad*1.3,rx:world?3:2,class:'atlas-nameplate-box'},parent);parent.insertBefore(rect,node);}
 return parent;
}
function relief(g,p,h=17){poly(g,p.map(([x,y])=>[x,y+h]),'atlas-cliff');poly(g,p,'atlas-surface');}
function box(g,x,y,w,d,h){poly(g,[[x,y],[x+w,y+12],[x+w,y+h+12],[x,y+h]],'atlas-face');poly(g,[[x+w,y+12],[x+w+d,y+12-d*.5],[x+w+d,y+h+12-d*.5],[x+w,y+h+12]],'atlas-shade');poly(g,[[x,y],[x+d,y-d*.5],[x+w+d,y+12-d*.5],[x+w,y+12]],'atlas-roof');}
function house(g,x,y,w=22,d=14,h=21){box(g,x,y,w,d,h);poly(g,[[x,y],[x+d/2,y-13],[x+w+d/2,y-1],[x+w,y+12]],'atlas-roof');poly(g,[[x+w,y+12],[x+w+d/2,y-1],[x+w+d,y+12-d*.5]],'atlas-face');path(g,`M${x+6} ${y+h*.5+10}v7`,'atlas-window');}
function turret(g,x,y,r,h,spire=false){el('ellipse',{cx:x,cy:y+h,rx:r,ry:r*.42,class:'atlas-shade'},g);path(g,`M${x-r} ${y}v${h}q${r} ${r*.8} ${2*r} 0v-${h}Z`,'atlas-face');el('ellipse',{cx:x,cy:y,rx:r,ry:r*.42,class:'atlas-roof'},g);if(spire){poly(g,[[x-r-2,y],[x,y-r*2.8],[x+r+2,y]],'atlas-roof');poly(g,[[x,y-r*2.8],[x+r+2,y],[x,y+r*.25]],'atlas-shade');}else for(let i=-1;i<=1;i++)box(g,x+i*r*.68-2,y-5,4,3,6);path(g,`M${x} ${y+12}v9`,'atlas-window');}
function mountain(g,x,y,w=25,h=35){poly(g,[[x-w,y+12],[x,y-h],[x+w,y+12],[x,y+20]],'atlas-mountain');poly(g,[[x,y-h],[x+w,y+12],[x,y+20]],'atlas-mountain-shade');path(g,`M${x-w*.35} ${y-h*.25}L${x} ${y-h}l${w*.25} ${h*.6}`,'atlas-ridge');}
function forest(g,x,y,r=5){poly(g,[[x-r,y+5],[x,y-r*2],[x+r,y+5]],'atlas-tree');}
function region(svg,id,draw){const g=el('g',{class:'atlas-region',role:'button',tabindex:0,'data-place':id,'aria-pressed':'false'},svg);draw(g);return g;}
function base(svg,title){el('title',{},svg).textContent=title;for(let i=0;i<5;i++)el('ellipse',{cx:500,cy:468,rx:120+i*87,ry:45+i*38,class:'atlas-sea-line'},svg);label(svg,60,55,'N ↑');label(svg,870,55,'ALTINEL / ATLAS');}
